// next/* を直接 import するライブラリ（next-intl などによくある形）
import { cookies, headers } from "next/headers";
import { notFound } from "next/navigation";
export { LocalePath } from "./client.js";

export async function getLocale() {
  const cookie = (await cookies()).get("locale")?.value;
  return cookie ?? (await headers()).get("accept-language") ?? "en";
}

export function requireLocale(locale) {
  if (locale !== "en" && locale !== "ja") notFound();
}
